<script setup lang="ts">
import {computed,reactive,ref,watch} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import type {Row} from '../api/types'
import {post,put} from '../api/http'
import {useAuth} from '../stores/auth'
import {useResource,useMutation,money,confirmAction} from '../composables/useResource'
import {useMediaQuery} from '../composables/useMediaQuery'
import RecordSelect from './RecordSelect.vue'
import RelatedRecords from './RelatedRecords.vue'
import {usePagedResource} from '../composables/usePagedResource'
import ResourceState from './ResourceState.vue'
import DataTable from './DataTable.vue'
const props=defineProps<{id:string|number}>(),auth=useAuth(),isMobile=useMediaQuery(),resource=useResource<any>(()=>`/contracts/${props.id}/payment-plan`,{stages:[],history:[],allocations:[],payments:[],refunds:[]})
function operationKey(){const bytes=new Uint8Array(16);crypto.getRandomValues(bytes);return [...bytes].map(b=>b.toString(16).padStart(2,'0')).join('')}
const rows=ref<Row[]>([]),replaceLegacy=ref(false),dirty=ref(false),allocationReference=ref(operationKey())
const canEdit=computed(()=>auth.can('contract:plan')&&auth.can('contract:write')&&auth.can('finance:read'))
watch(()=>resource.data.value,m=>{rows.value=(m.stages||[]).map((r:Row)=>({...r,amount:String(r.amount),due_date:r.due_date||''}));replaceLegacy.value=false;dirty.value=false},{immediate:true})
const allocationList=usePagedResource(()=>auth.can('finance:read')?`/records/plan-allocations?contract_id=${props.id}`:'')
async function reload(){await Promise.all([resource.load(),allocationList.load()])}
const {saving,run}=useMutation(reload),allocation=reactive({stage_id:'' as any,source_type:'PAYMENT',source_id:'' as any,amount:''})
const sourceRows=computed<Row[]>(()=>allocation.source_type==='PAYMENT'?resource.data.value.payments||[]:resource.data.value.refunds||[])
watch(()=>allocation.source_type,()=>{allocation.source_id='';allocation.amount=''})
function cents(value:any):bigint|null{const s=String(value??'').trim();if(!/^\d+(\.\d{1,2})?$/.test(s))return null;const [a,b='']=s.split('.');return BigInt(a!)*100n+BigInt(b.padEnd(2,'0'))}
const planned=computed(()=>{let total=0n;for(const r of rows.value){const n=cents(r.amount);if(n===null)return null;total+=n}return total})
function display(n:bigint|null){if(n===null)return '金额待核实';const sign=n<0n?'-':'';let s=(n<0n?-n:n).toString().padStart(3,'0');return sign+s.slice(0,-2).replace(/\B(?=(\d{3})+(?!\d))/g,',')+'.'+s.slice(-2)}
const remainder=computed(()=>{const total=cents(resource.data.value.contract_amount);return total===null||planned.value===null?null:total-planned.value})
function add(){rows.value.push({id:'' as any,stage_name:'',due_date:'',amount:'',note:'',can_delete:true});dirty.value=true}
function move(i:number,delta:number){const j=i+delta;if(j<0||j>=rows.value.length)return;[rows.value[i],rows.value[j]]=[rows.value[j]!,rows.value[i]!];dirty.value=true}
function drop(i:number){rows.value.splice(i,1);dirty.value=true}
async function refresh(){if(dirty.value&&!await confirmAction('刷新将丢弃当前未保存的计划编辑，是否继续？'))return;await resource.load()}
async function save(){if(!canEdit.value)return;if(rows.value.some(r=>!r.stage_name?.trim()||cents(r.amount)===null)){ElMessage.warning('请填写阶段名称和最多两位小数的非负金额');return}if(resource.data.value.legacy_warning&&!replaceLegacy.value){ElMessage.warning('请先确认保留旧计划原文后重建');return}const payload={expected_version:resource.data.value.version,replace_legacy:replaceLegacy.value,stages:rows.value.map(r=>({id:r.id||undefined,stage_name:r.stage_name,due_date:r.due_date||null,amount:r.amount,note:r.note||''}))};if(await run(()=>put(`/contracts/${props.id}/payment-plan`,payload),'付款计划已保存'))dirty.value=false}
async function allocate(){if(!allocation.stage_id||!allocation.source_id||cents(allocation.amount)===null||cents(allocation.amount)===0n){ElMessage.warning('请选择阶段和实际记录，并填写明确关联金额');return}if(await run(()=>post(`/contracts/${props.id}/payment-allocations`,{...allocation,reference:allocationReference.value}),'实际记录已人工关联')){allocation.amount='';allocationReference.value=operationKey()}}
async function cancel(row:Row){try{const {value}=await ElMessageBox.prompt('只取消阶段关联，不改变原付款或退款。请填写原因。','取消关联',{inputValidator:v=>!!v?.trim()&&v.length<=1000||'请填写原因（最多1000字）',confirmButtonText:'确认取消关联',cancelButtonText:'返回'});await run(()=>post(`/contracts/${props.id}/payment-allocations/${row.id}/void`,{reason:value}),'关联已取消，历史记录保留')}catch{}}
defineExpose({save,saving,dirty})
</script>
<template><ResourceState :loading="resource.loading.value" :error="resource.error.value" @retry="resource.load"><div class="subheading"><h3>约定付款阶段</h3><div><el-button @click="refresh">刷新计划</el-button><el-button v-if="canEdit" type="primary" plain @click="add">＋ 新增阶段</el-button></div></div><el-alert v-if="resource.data.value.legacy_warning" :title="resource.data.value.legacy_warning" type="warning" show-icon :closable="false" class="mb"/><details v-if="resource.data.value.legacy_raw&&resource.data.value.legacy_warning" class="mb"><summary>查看保留的旧计划原文</summary><pre class="legacy-plan">{{resource.data.value.legacy_raw}}</pre></details><el-checkbox v-if="resource.data.value.legacy_warning&&canEdit" v-model="replaceLegacy">我已核实旧计划，保留原文后重建</el-checkbox><div class="summary-strip"><div><span>合同金额</span><b>¥ {{money(resource.data.value.contract_amount)}}</b></div><div><span>当前计划预览</span><b>{{resource.data.value.legacy_warning&&!replaceLegacy?'旧计划待核实':'¥ '+display(planned)}}</b></div><div><span>未分配金额预览</span><b>{{resource.data.value.legacy_warning&&!replaceLegacy?'旧计划待核实':'¥ '+display(remainder)}}</b></div></div><p class="field-hint">允许合同金额未分配完；日期可未约定，未约定不生成到期提醒。预览不代表付款，保存时由服务端重新校验。</p>
<div v-if="isMobile" class="mobile-form-lines"><section v-for="(row,i) in rows" :key="row.id||`new-${i}`" class="mobile-form-line"><div class="subheading"><h3>阶段 {{i+1}}</h3><div v-if="canEdit"><el-button :disabled="i===0" @click="move(i,-1)">上移</el-button><el-button :disabled="i===rows.length-1" @click="move(i,1)">下移</el-button><el-button type="danger" plain :disabled="!!row.id&&!row.can_delete" @click="drop(i)">删除</el-button></div></div><el-form label-position="top" :disabled="!canEdit" @change="dirty=true"><el-form-item label="付款阶段"><el-input v-model="row.stage_name" maxlength="120" @input="dirty=true"/></el-form-item><el-form-item label="约定日期（可未约定）"><el-date-picker v-model="row.due_date" type="date" value-format="YYYY-MM-DD" style="width:100%" @change="dirty=true"/></el-form-item><el-form-item label="计划金额（元）"><el-input v-model="row.amount" inputmode="decimal" @input="dirty=true"/></el-form-item><el-form-item label="备注"><el-input v-model="row.note" type="textarea" :rows="2" maxlength="1000" @input="dirty=true"/></el-form-item></el-form><p v-if="row.linked_net_paid!==undefined" class="field-hint">已关联净付款 ¥ {{money(row.linked_net_paid)}}{{row.due_for_review?' · 约定日期已到，需核对关联':''}}</p></section></div>
<el-table v-else :data="rows" border empty-text="暂无付款阶段"><el-table-column label="阶段" min-width="140"><template #default="{row}"><el-input v-model="row.stage_name" :disabled="!canEdit" maxlength="120" @input="dirty=true"/></template></el-table-column><el-table-column label="约定日期" width="180"><template #default="{row}"><el-date-picker v-model="row.due_date" :disabled="!canEdit" type="date" value-format="YYYY-MM-DD" style="width:100%" @change="dirty=true"/></template></el-table-column><el-table-column label="金额（元）" width="140"><template #default="{row}"><el-input v-model="row.amount" :disabled="!canEdit" inputmode="decimal" @input="dirty=true"/></template></el-table-column><el-table-column label="备注" min-width="150"><template #default="{row}"><el-input v-model="row.note" :disabled="!canEdit" maxlength="1000" @input="dirty=true"/></template></el-table-column><el-table-column v-if="auth.can('finance:read')" label="已关联净付款" width="150"><template #default="{row}">{{money(row.linked_net_paid)}}</template></el-table-column><el-table-column v-if="canEdit" label="排序 / 删除" width="190"><template #default="{row,$index}"><el-button link :disabled="$index===0" @click="move($index,-1)">上移</el-button><el-button link :disabled="$index===rows.length-1" @click="move($index,1)">下移</el-button><el-button link type="danger" :disabled="!!row.id&&!row.can_delete" @click="drop($index)">删除</el-button></template></el-table-column></el-table>
<p class="field-hint">有实际关联历史的阶段不能直接删除。关联净付款只表示明确分配到阶段的记录；未关联的付款或退款不按日期、金额猜测分配。</p>
<section v-if="auth.can('finance:read')" class="mt"><h3>实际记录人工关联</h3><el-alert v-if="!resource.data.value.actuals_supported" title="该合同没有关联采购应付，当前无法准确核对实际付款；计划仍可维护。" type="info" :closable="false" class="mb"/><template v-else><p class="field-hint">只列当前合同关联订单的实际付款或退款。先保存阶段，再由财务明确选择记录和金额。</p><el-form v-if="auth.can('finance:write')" label-position="top"><div class="form-grid"><el-form-item label="关联阶段"><el-select v-model="allocation.stage_id" placeholder="选择已保存阶段"><el-option v-for="s in resource.data.value.stages.filter((s:Row)=>!!s.id)" :key="s.id" :value="s.id" :label="s.stage_name"/></el-select></el-form-item><el-form-item label="记录类型"><el-select v-model="allocation.source_type"><el-option label="实际付款" value="PAYMENT"/><el-option label="实际退款" value="REFUND"/></el-select></el-form-item><el-form-item label="实际记录"><RecordSelect v-model="allocation.source_id" :entity="allocation.source_type==='PAYMENT'?'payments':'supplier-refunds'" :filters="{order_id:resource.data.value.order_id}"/></el-form-item><el-form-item label="明确关联金额（元）"><el-input v-model="allocation.amount" inputmode="decimal" placeholder="由财务核实后填写"/></el-form-item></div><el-button type="primary" plain :loading="saving" @click="allocate">确认人工关联</el-button></el-form><DataTable :remote="allocationList.paging" @page="allocationList.onPage" @size="allocationList.onSize" @search="allocationList.onSearch" :rows="allocationList.data.value" :columns="[{key:'stage_name',label:'阶段'},{key:'source_type',label:'记录类型'},{key:'source_reference',label:'实际凭证',minWidth:180},{key:'amount',label:'关联金额',money:true},{key:'operator_name',label:'关联人'},{key:'created_at',label:'关联时间',date:true},{key:'voided',label:'关联状态'},{key:'void_reason',label:'取消原因'}]"><template #source_type="{row}">{{row.source_type==='PAYMENT'?'付款':'退款'}}</template><template #voided="{row}">{{row.voided?'已取消关联':'有效关联'}}</template><template v-if="auth.can('finance:write')" #actions="{row}"><el-button link type="danger" :disabled="!!row.voided" @click="cancel(row)">取消关联</el-button></template></DataTable></template></section>
<RelatedRecords class="mt" entity="plan-history" :filters="{contract_id:id}" :columns="[{key:'id',label:'计划变更编号'},{key:'operator_name',label:'操作人'},{key:'created_at',label:'变更时间',date:true}]"/>
</ResourceState></template>
<style scoped>.legacy-plan{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;line-height:1.8;padding:12px;background:#f6f8fc;border:1px solid #e5eaf2;border-radius:6px}.subheading>div{display:flex;gap:6px;flex-wrap:wrap}.subheading .el-button{margin:0}</style>
